#pragma once

#include <cstddef>
#include <cstdint>

namespace mge {

    enum class ShaderStage {
        Vertex,
        Fragment,
        Compute
    };

    // Compiled shader bytecode embedded in the binary: generated by mge_add_shaders and
    // cmake/MgeEmbedSpirv.cmake as mge::shaders::k<Name><Stage>.
    // SPIR-V is always embedded (Vulkan); MSL source is also embedded when MGE_SHADERS_MSL=ON (Metal).
    struct ShaderCode {
        const std::uint8_t* code = nullptr;
        std::size_t size = 0;
        ShaderStage stage = ShaderStage::Vertex;
        const std::uint8_t* mslCode = nullptr;
        std::size_t mslSize = 0;
    };

    // How many resources of each kind a shader uses (SDL GPU does not deduce them from SPIR-V).
    // Binding convention for GLSL → SPIR-V (required by SDL GPU):
    //   vertex:   set 0 = sampled textures, storage textures, storage buffers; set 1 = uniform buffers
    //   fragment: set 2 = sampled textures, storage textures, storage buffers; set 3 = uniform buffers
    //   compute:  set 0 = sampled textures, read-only storage textures, and read-only storage buffers;
    //             set 1 = read-write storage textures and storage buffers;
    //             set 2 = uniform buffers
    // Within each set, bindings are assigned in that order starting from 0.
    struct ShaderResources {
        std::uint32_t samplers = 0;
        std::uint32_t storageTextures = 0;
        std::uint32_t storageBuffers = 0;
        std::uint32_t uniformBuffers = 0;
    };
}
